        excludedTurns: integer2("excluded_turns").notNull().default(0),
        redactions: integer2("redactions").notNull().default(0),
        models: text5("models").array().notNull().default(sql`'{}'::text[]`),
        // Run facts, null on rows ingested before parser version 4.
