        houseCassetteSha256: sha2563("house_cassette_sha256"),
        /** That cassette's totals.micro_usd: what the pass's calls to the target cost the house, never the entry. Set with house_cassette_sha256. */
        houseSpendMicroUsd: microUsd("house_spend_micro_usd"),
        /** What the trial's voided live passes cost on the house lane, summed as voided_spend_micro_usd sums the entry's lane. */
        voidedHouseSpendMicroUsd: microUsd("voided_house_spend_micro_usd").notNull().default(sql`0`),
