        check2("claim_clearance_ip_country_shape", nullOr(t2.ipCountry, sql`${t2.ipCountry} ~ '^[A-Z0-9]{2}$'`)),
        // A region is read only of a known country (not XX, T1 or none), and is a subdivision of it.
        check2("claim_clearance_ip_region_read", sql`NOT ${t2.ipRegionRead} OR (${t2.ipCountry} IS NOT NULL AND ${t2.ipCountry} ~ '^[A-Z]{2}$' AND ${t2.ipCountry} <> 'XX')`),
        check2("claim_clearance_ip_region_shape", nullOr(t2.ipRegion, sql`${t2.ipRegionRead} AND ${t2.ipRegion} ~ '^[A-Z]{2}-[A-Z0-9]{1,3}$' AND left(${t2.ipRegion}, 3) = ${t2.ipCountry} || '-'`)),
        check2("claim_clearance_reasons", sql`${t2.reasons} <@ ARRAY[${sql.raw(CLAIM_CHECK_IDS.map((c2) => `'${c2}'`).join(", "))}]::text[]`),
        check2("claim_clearance_clear_has_no_reasons", sql`(${t2.decision} = 'clear') = (cardinality(${t2.reasons}) = 0)`)
