        depositedAt: tz("deposited_at"),
        status: sponsorAllowanceStatus("status").notNull().default("pending"),
        /** What the competition's build keys spent, settled (micro-USD); fixed by the sweep at refund_owed. */
        spentMicroUsd: microUsd("spent_micro_usd"),
        /** What is owed back (cents): the deposit less the spend rounded up to the cent, never below 0; fixed with spent_micro_usd. */
        refundCents: bigint4("refund_cents", { mode: "bigint" }),
        /** The refund's transfer (base58 signature), checked on the manual rail (server/payouts/rails.ts checkTxRef). */
