        check2("allowance_refund_send_times", sql`(${t2.landedAt} IS NULL OR ${t2.landedAt} >= ${t2.createdAt}) AND (${t2.finalizedAt} IS NULL OR ${t2.finalizedAt} >= ${t2.landedAt})`)
