        flags: jsonb("flags").$type().notNull().default(sql`'[]'::jsonb`),
        /** The body's links as the pipeline classified them at post, in body order; never re-derived from the body. */
        links: jsonb("links").$type().notNull().default(sql`'[]'::jsonb`),
        /** The links' hosts (lowercase ASCII): a newly listed host holds every published comment that carries it (link_hosts && the hosts). */
        linkHosts: text5("link_hosts").array().notNull().default(sql`'{}'::text[]`),
        /** The Solana addresses (base58) the body names. */
        addresses: text5("addresses").array().notNull().default(sql`'{}'::text[]`),
        /** sha256 of the folded body, whitespace collapsed and punctuation stripped: the same text from one account or from many. Null on a comment from before 0025. */
        fingerprint: sha2563("fingerprint"),
        /** Likes, and the likes of accounts trusted when they liked (the Top sort's count). */
        likeCount: integer2("like_count").notNull().default(0),
        trustedLikeCount: integer2("trusted_like_count").notNull().default(0),
        /** On a root, its replies (root_id this comment) that are not deleted; 0 on a reply. */
