  const publicProblem = set3("MAKEFUN_LLM_GATEWAY_PUBLIC_URL") && "origin" in publicUrl ? publicGatewayUrlProblem(publicUrl.origin, env.NODE_ENV) : null;
  if (publicProblem !== null) issues.push(`MAKEFUN_LLM_GATEWAY_PUBLIC_URL: ${publicProblem}`);
  const minAllowance = parseSponsorPrizeUsd(env.MAKEFUN_SPONSOR_MIN_ALLOWANCE_USD, "unset");
  const maxAllowance = parseSponsorPrizeUsd(env.MAKEFUN_SPONSOR_MAX_ALLOWANCE_USD, "unset");
